def top_k_counts(words: list[str], k: int) -> list[tuple[str,int]]:
    if k <= 0 or not words:
        return []
    first_spelling = {}
    first_pos = {}
    counts = {}
    for idx, w in enumerate(words):
        key = w.lower()
        if key not in first_spelling:
            first_spelling[key] = w
            first_pos[key] = idx
        counts[key] = counts.get(key, 0) + 1

    items = []
    for key, cnt in counts.items():
        items.append((first_spelling[key], cnt, first_pos[key]))
    items.sort(key=lambda x: (-x[1], x[2]))
    return [(word, cnt) for word, cnt, _ in items[:k]]
