import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid = 0
    services = {}

    for line in lines:
        s = line.strip()
        if not s:
            continue
        try:
            obj = json.loads(s)
        except Exception:
            invalid += 1
            continue
        if not isinstance(obj, dict):
            invalid += 1
            continue

        service = obj.get('service')
        latency_ms = obj.get('latency_ms')
        status = obj.get('status')

        if not isinstance(service, str):
            invalid += 1
            continue
        if not isinstance(latency_ms, (int, float)) or isinstance(latency_ms, bool):
            invalid += 1
            continue
        if not isinstance(status, (int, float)) or isinstance(status, bool):
            invalid += 1
            continue

        if service not in services:
            services[service] = {'latencies': [], 'ok': 0, 'total': 0}
        entry = services[service]
        entry['latencies'].append(latency_ms)
        entry['total'] += 1
        if 200 <= status < 300:
            entry['ok'] += 1

    result = {'invalid': invalid}
    for svc in sorted(services.keys()):
        entry = services[svc]
        n = entry['total']
        ok_rate = entry['ok'] / n if n else 0.0
        latencies = entry['latencies']
        if n:
            latencies.sort()
            idx = math.ceil(0.95 * n) - 1
            if idx < 0:
                idx = 0
            if idx >= n:
                idx = n - 1
            p95 = latencies[idx]
        else:
            p95 = None
        result[svc] = {'count': n, 'ok_rate': ok_rate, 'p95_latency_ms': p95}
    return result
