import heapq
import sys

sys.setrecursionlimit(1000000)

class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__(f"Cycle detected: {'->'.join(cycle)}")
        self.cycle = cycle

def dependency_plan(nodes, edges):
    uniq_nodes = []
    seen_n = set()
    for n in nodes:
        if n not in seen_n:
            seen_n.add(n)
            uniq_nodes.append(n)
    nodes_set = set(uniq_nodes)

    adj = {n: set() for n in nodes_set}
    indegree = {n: 0 for n in nodes_set}
    seen_edge = set()

    for a, b in edges:
        if a not in nodes_set or b not in nodes_set:
            raise ValueError(f"Unknown node in edge {(a, b)}")
        if (a, b) in seen_edge:
            continue
        seen_edge.add((a, b))
        if b not in adj[a]:
            adj[a].add(b)
            indegree[b] += 1

    heap = [n for n in nodes_set if indegree[n] == 0]
    heapq.heapify(heap)
    result = []
    indeg = indegree.copy()
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)

    if len(result) == len(uniq_nodes):
        return result

    visited = set()
    onstack = set()
    stack = []
    cycle = None

    def dfs(u):
        nonlocal cycle
        visited.add(u)
        onstack.add(u)
        stack.append(u)
        for v in sorted(adj.get(u, [])):
            if v not in visited:
                if dfs(v):
                    return True
            elif v in onstack:
                idx = stack.index(v)
                cycle = stack[idx:] + [v]
                return True
        stack.pop()
        onstack.remove(u)
        return False

    for n in sorted(nodes_set):
        if n not in visited:
            if dfs(n):
                break
    if cycle is None:
        cycle = []
    raise CycleError(cycle)
