def streaming_group_sum(rows):
    class _Grouper:
        def __init__(self, rows):
            self.rows = rows
            self.invalid_count = 0
            self._sums = None
            self._done = False

        def __iter__(self):
            if self._done:
                for k, v in self._sums.items():
                    yield (k, v)
                return
            sums = {}
            invalid = 0
            for row in self.rows:
                try:
                    if not isinstance(row, (list, tuple)) or len(row) != 3:
                        raise ValueError
                    _, key, val = row
                    if isinstance(val, bool) or not isinstance(val, (int, float)):
                        raise TypeError
                    if key not in sums:
                        sums[key] = 0
                    sums[key] += val
                except Exception:
                    invalid += 1
                    continue
            self.invalid_count = invalid
            self._sums = sums
            self._done = True
            for k, v in sums.items():
                yield (k, v)

    return _Grouper(rows)
