import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be > 0")
    last_exc = None
    for i in range(attempts):
        try:
            return fn()
        except Exception as e:
            last_exc = e
            if i == attempts - 1 or not retry_if(e):
                raise
            sleep(base_delay * 2 ** i)
    raise last_exc
