import copy

def apply_patch_ops(document: dict, operations) -> dict:
    new_doc = copy.deepcopy(document)
    for op, path, value in operations:
        if not isinstance(path, str) or not path:
            raise ValueError("invalid path")
        parts = path.split('.')
        if op == 'set':
            cur = new_doc
            for part in parts[:-1]:
                if not isinstance(cur, dict):
                    raise TypeError(f"path {path} traverses non-dict")
                if part not in cur or not isinstance(cur[part], dict):
                    cur[part] = {}
                cur = cur[part]
            cur[parts[-1]] = copy.deepcopy(value)
        elif op == 'delete':
            cur = new_doc
            try:
                for part in parts[:-1]:
                    cur = cur[part]
                    if not isinstance(cur, dict):
                        raise StopIteration
            except (KeyError, TypeError, StopIteration):
                continue
            if isinstance(cur, dict) and parts[-1] in cur:
                del cur[parts[-1]]
        elif op == 'increment':
            cur = new_doc
            for part in parts[:-1]:
                if not isinstance(cur, dict) or part not in cur:
                    raise KeyError(f"path {path} not found")
                cur = cur[part]
                if not isinstance(cur, dict):
                    raise TypeError(f"path {path} traverses non-dict")
            key = parts[-1]
            if not isinstance(cur, dict) or key not in cur:
                raise KeyError(f"path {path} not found")
            current = cur[key]
            if type(current) not in (int, float):
                raise TypeError("increment target not numeric")
            if type(value) not in (int, float):
                raise TypeError("increment value not numeric")
            cur[key] = current + value
        else:
            raise ValueError(f"unknown op {op}")
    return new_doc
