import threading
import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        self.maxsize = maxsize
        self.ttl = ttl
        self.clock = clock
        self._data = OrderedDict()
        self._lock = threading.RLock()

    def _now(self):
        return self.clock()

    def _purge_expired_locked(self):
        now = self._now()
        for k in list(self._data.keys()):
            if now >= self._data[k][1]:
                del self._data[k]

    def get(self, key, default=None):
        with self._lock:
            if key not in self._data:
                return default
            value, expire = self._data[key]
            if self._now() >= expire:
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key, value):
        with self._lock:
            now = self._now()
            expire = now + self.ttl
            if key in self._data:
                self._data[key] = (value, expire)
            else:
                self._data[key] = (value, expire)
            self._data.move_to_end(key)
            self._purge_expired_locked()
            while len(self._data) > self.maxsize:
                self._data.popitem(last=False)

    def delete(self, key):
        with self._lock:
            if key in self._data:
                del self._data[key]
                return True
            return False

    def __len__(self):
        with self._lock:
            self._purge_expired_locked()
            return len(self._data)
