import threading
import time

class SingleFlightTTLCache:
    def __init__(self, ttl=60):
        self.ttl = ttl
        self._cache = {}
        self._lock = threading.RLock()
        self._inflight = {}
        self._inflight_lock = threading.RLock()

    def _now(self):
        return time.time()

    def get(self, key, default=None):
        with self._lock:
            entry = self._cache.get(key)
            if not entry:
                return default
            val, exp = entry
            if self._now() >= exp:
                del self._cache[key]
                return default
            return val

    def set(self, key, value, ttl=None):
        exp = self._now() + (ttl if ttl is not None else self.ttl)
        with self._lock:
            self._cache[key] = (value, exp)

    def delete(self, key):
        with self._lock:
            self._cache.pop(key, None)

    def __len__(self):
        with self._lock:
            now = self._now()
            dead = [k for k, (_, exp) in self._cache.items() if exp <= now]
            for k in dead:
                del self._cache[k]
            return len(self._cache)

    def get_or_load(self, key, loader):
        with self._lock:
            entry = self._cache.get(key)
            if entry:
                val, exp = entry
                if self._now() < exp:
                    return val
                del self._cache[key]

        with self._inflight_lock:
            if key in self._inflight:
                inflight = self._inflight[key]
                event = inflight['event']
                is_leader = False
            else:
                event = threading.Event()
                inflight = {'event': event, 'result': None, 'exc': None}
                self._inflight[key] = inflight
                is_leader = True

        if not is_leader:
            event.wait()
            if inflight['exc'] is not None:
                raise inflight['exc']
            return inflight['result']

        try:
            result = loader()
            self.set(key, result)
            inflight['result'] = result
        except Exception as e:
            inflight['exc'] = e
            raise
        finally:
            with self._inflight_lock:
                if self._inflight.get(key) is inflight:
                    del self._inflight[key]
                event.set()
        return result
