import threading


class _Entry:
    __slots__ = ("event", "result", "exc", "done")
    def __init__(self):
        self.event = threading.Event()
        self.result = None
        self.exc = None
        self.done = False


class IdempotentEventProcessor:
    def __init__(self, apply):
        self.apply = apply
        self._lock = threading.RLock()
        self._entries = {}

    def process(self, event_id, payload):
        with self._lock:
            entry = self._entries.get(event_id)
            if entry:
                if entry.done:
                    if entry.exc is None:
                        return entry.result
                    else:
                        del self._entries[event_id]
                        entry = None
            if not entry:
                entry = _Entry()
                self._entries[event_id] = entry
                owner = True
            else:
                owner = False

        if not owner:
            entry.event.wait()
            with self._lock:
                if entry.exc:
                    raise entry.exc
                if entry.done:
                    return entry.result
            raise RuntimeError("unexpected state")

        try:
            res = self.apply(payload)
            with self._lock:
                entry.result = res
                entry.done = True
                entry.event.set()
            return res
        except Exception as e:
            with self._lock:
                entry.exc = e
                entry.done = True
                entry.event.set()
                if self._entries.get(event_id) is entry:
                    del self._entries[event_id]
            raise

    def result(self, event_id):
        with self._lock:
            entry = self._entries.get(event_id)
            if not entry or not entry.done or entry.exc is not None:
                raise KeyError(event_id)
            return entry.result
