import threading
from collections import deque

class BoundedQueue:
    def __init__(self, capacity):
        self._q = deque()
        self._cap = capacity
        self._closed = False
        self._cond = threading.Condition(threading.Lock())

    def put(self, item):
        with self._cond:
            if self._closed:
                raise RuntimeError("Queue closed")
            while len(self._q) >= self._cap:
                if self._closed:
                    raise RuntimeError("Queue closed")
                self._cond.wait()
            self._q.append(item)
            self._cond.notify()

    def get(self):
        with self._cond:
            while not self._q:
                if self._closed:
                    raise RuntimeError("Queue closed")
                self._cond.wait()
            item = self._q.popleft()
            self._cond.notify()
            return item

    def close(self):
        with self._cond:
            if self._closed:
                return
            self._closed = True
            self._cond.notify_all()
